<script setup lang="ts">
import { formatAmountMinor } from '../../../../domain/expense'
const route = useRoute(); const router = useRouter(); const groupsStore = useGroupsStore(); const { remove } = useExpenses()
const groupId = computed(() => String(route.params.id)); const expenseId = computed(() => String(route.params.expenseId)); const group = computed(() => groupsStore.findGroup(groupId.value)); const expense = computed(() => groupsStore.expenses.find(item => item.id === expenseId.value && item.groupId === groupId.value)); const participants = computed(() => new Map(groupsStore.participantsForGroup(groupId.value).map(item => [item.id, item])))
const editing = ref(false); const dialog = ref<HTMLDialogElement | null>(null); const cancelDeleteButton = ref<HTMLButtonElement | null>(null); const deleteButton = ref<HTMLButtonElement | null>(null); const deleteTrigger = ref<HTMLButtonElement | null>(null); const heading = ref<HTMLHeadingElement | null>(null); const status = ref(''); const deleteError = ref(''); const deleting = ref(false)
async function focusHeading() { await nextTick(); heading.value?.focus() }
async function saved() { editing.value = false; status.value = 'Änderungen wurden lokal gespeichert.'; await focusHeading() }
async function startEditing() { editing.value = true; await nextTick(); document.querySelector<HTMLInputElement>('#expense-description')?.focus() }
function askDelete() { status.value = ''; deleteError.value = ''; dialog.value?.showModal(); nextTick(() => cancelDeleteButton.value?.focus()) }
function cancelDelete() { if (deleting.value) return; dialog.value?.close(); nextTick(() => deleteTrigger.value?.focus()) }
async function confirmDelete() {
  if (!expense.value || deleting.value) return
  status.value = ''; deleting.value = true
  try { await remove(expense.value); dialog.value?.close(); await router.push(`/groups/${groupId.value}?deleted=1`) }
  catch { deleteError.value = 'Die Ausgabe konnte nicht lokal gelöscht werden.'; deleting.value = false; await nextTick(); deleteButton.value?.focus() }
  finally { deleting.value = false }
}
onMounted(() => { if (route.query.created === '1') void focusHeading() })
</script>
<template><main class="page-shell"><div v-if="group && expense" class="page-content"><NuxtLink :to="`/groups/${group.id}`" class="secondary-link -ml-4 mb-3"><AppIcon name="arrow-left" />Ausgaben</NuxtLink><header class="min-w-0"><p class="break-words text-sm font-semibold tracking-wide text-brand-700">{{ group.name }}</p><h1 ref="heading" tabindex="-1" class="mt-2 break-words text-3xl font-semibold text-brand-900">{{ expense.description }}</h1></header><p v-if="route.query.created === '1'" class="mt-5 rounded-lg bg-brand-50 p-3 text-brand-900" role="status">Ausgabe lokal gespeichert.</p><GroupSyncStatus :group-id="group.id" class="mt-4" /><p v-if="status" class="mt-4" :role="status.includes('konnte nicht') ? 'alert' : 'status'">{{ status }}</p><ExpenseForm v-if="editing" class="mt-6" :group-id="group.id" :expense="expense" @saved="saved" /><template v-else><dl class="card mt-6 grid min-w-0 grid-cols-1 gap-4 p-5 sm:grid-cols-2"><div><dt class="text-sm text-gray-600">Betrag</dt><dd class="font-semibold">{{ formatAmountMinor(expense.amountMinor) }}</dd></div><div><dt class="text-sm text-gray-600">Datum</dt><dd class="font-semibold">{{ expense.incurredOn }}</dd></div><div class="min-w-0 sm:col-span-2"><dt class="text-sm text-gray-600">Bezahlt von</dt><dd class="break-words font-semibold">{{ participants.get(expense.payerParticipantId)?.name }}</dd></div></dl><section class="card mt-5 min-w-0 p-5" aria-labelledby="shares-title"><h2 id="shares-title" class="text-xl font-semibold">Aufteilung</h2><ul class="mt-3 space-y-2"><li v-for="share in expense.shares" :key="share.participantId" class="flex min-w-0 flex-wrap justify-between gap-4"><span class="min-w-0 break-words">{{ participants.get(share.participantId)?.name }}</span><strong>{{ formatAmountMinor(share.amountMinor) }}</strong></li></ul></section><div v-if="group.status === 'active'" class="mt-5 grid gap-3 sm:grid-cols-2"><button type="button" class="secondary-button" @click="startEditing"><AppIcon name="pencil" />Bearbeiten</button><button ref="deleteTrigger" type="button" class="danger-button" @click="askDelete"><AppIcon name="trash" />Ausgabe löschen</button></div><p v-else class="card mt-5 p-4">Diese archivierte Gruppe ist schreibgeschützt.</p></template><dialog ref="dialog" role="alertdialog" class="delete-dialog rounded-2xl p-0" aria-labelledby="expense-delete-title" aria-describedby="expense-delete-description" :aria-busy="deleting" @cancel.prevent="cancelDelete"><div class="min-w-0 p-5"><h2 id="expense-delete-title" class="text-xl font-semibold">Ausgabe löschen</h2><p id="expense-delete-description" class="mt-3 break-words">Ausgabe „{{ expense.description }}“ endgültig löschen?</p><p v-if="deleteError" class="error-text mt-3" role="alert">{{ deleteError }}</p><div class="mt-5 flex flex-wrap gap-2"><button ref="cancelDeleteButton" type="button" class="secondary-button" :disabled="deleting" @click="cancelDelete">Abbrechen</button><button ref="deleteButton" type="button" class="danger-button" :disabled="deleting" @click="confirmDelete">{{ deleting ? 'Wird gelöscht …' : 'Endgültig löschen' }}</button></div></div></dialog></div><div v-else class="page-content"><h1 class="text-3xl font-semibold">Ausgabe nicht gefunden</h1><NuxtLink :to="`/groups/${groupId}`" class="secondary-link mt-5"><AppIcon name="arrow-left" />Zur Gruppe</NuxtLink></div></main></template>
